package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.regex.Pattern;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the settings form from the body; refuses a clerk limit or floor that is negative or has more than two
 *  decimals, and terms that are not a whole number of days, and a late percent that is negative or has more than two decimals, and a policy date or period numbering from that is not a calendar date
 *  (YYYY-MM-DD). A blank clerk limit means no limit; a blank floor is
 *  1.00; blank terms are 14; a blank late percent is 0.00; a blank policy date is the sheet's today; a blank period numbering from is off; a blank cap is none (else an amount like the floor). A grade's terms must be a whole number of days, or blank (the grade uses the sheet's terms). A key left out is not changed. */
public class ValidateSettings {

    private static final Pattern DAYS = Pattern.compile("\\d{1,5}");

    private static final Pattern AMOUNT = Pattern.compile("\\d+(\\.\\d{1,2})?");

    public void validate(@RequestBody SettingsRequest request, Out<SettingsInput> body) throws InvalidSettingsException {
        String limit = request == null ? null : request.clerkLimit();
        String floor = request == null ? null : request.floor();
        BigDecimal limitValue = null;
        if (limit != null && !limit.trim().isEmpty()) {
            if (!AMOUNT.matcher(limit.trim()).matches()) {
                throw new InvalidSettingsException("The clerk limit must be an amount, 0.00 or more, with up to two decimals, or blank.");
            }
            limitValue = new BigDecimal(limit.trim()).setScale(2);
        }
        BigDecimal floorValue = Sheet.DEFAULT_FLOOR;
        if (floor != null && !floor.trim().isEmpty()) {
            if (!AMOUNT.matcher(floor.trim()).matches()) {
                throw new InvalidSettingsException("The floor must be an amount, 0.00 or more, with up to two decimals, or blank.");
            }
            floorValue = new BigDecimal(floor.trim()).setScale(2);
        }
        String terms = request == null ? null : request.terms();
        int termsValue = Sheet.DEFAULT_TERMS;
        if (terms != null && !terms.trim().isEmpty()) {
            if (!DAYS.matcher(terms.trim()).matches()) {
                throw new InvalidSettingsException("The terms must be a whole number of days, 0 or more, or blank.");
            }
            termsValue = Integer.parseInt(terms.trim());
        }
        String late = request == null ? null : request.latePct();
        BigDecimal lateValue = Sheet.DEFAULT_LATE_PCT;
        if (late != null && !late.trim().isEmpty()) {
            if (!AMOUNT.matcher(late.trim()).matches()) {
                throw new InvalidSettingsException("The late percent must be a percent, 0.00 or more, with up to two decimals, or blank.");
            }
            lateValue = new BigDecimal(late.trim()).setScale(2);
        }
        String policy = request == null ? null : request.policyDate();
        LocalDate policyValue = null;
        if (policy != null && !policy.trim().isEmpty()) {
            try {
                policyValue = LocalDate.parse(policy.trim());
            } catch (DateTimeParseException e) {
                throw new InvalidSettingsException("The policy date must be a date (YYYY-MM-DD), or blank.");
            }
        }
        String numbering = request == null ? null : request.periodNumberingFrom();
        LocalDate numberingValue = null;
        if (numbering != null && !numbering.trim().isEmpty()) {
            try {
                numberingValue = LocalDate.parse(numbering.trim());
            } catch (DateTimeParseException e) {
                throw new InvalidSettingsException("The period numbering from must be a date (YYYY-MM-DD), or blank.");
            }
        }
        Map<String, Integer> gradeTerms = new LinkedHashMap<>();
        if (request != null) {
            gradeTerms(gradeTerms, "A", request.termsA());
            gradeTerms(gradeTerms, "B", request.termsB());
            gradeTerms(gradeTerms, "C", request.termsC());
        }
        String cap = request == null ? null : request.cap();
        BigDecimal capValue = null;
        if (cap != null && !cap.trim().isEmpty()) {
            if (!AMOUNT.matcher(cap.trim()).matches()) {
                throw new InvalidSettingsException("The cap must be an amount, 0.00 or more, with up to two decimals, or blank.");
            }
            capValue = new BigDecimal(cap.trim()).setScale(2);
        }
        body.set(new SettingsInput(limit != null, limitValue, floor != null, floorValue, terms != null, termsValue,
                late != null, lateValue, policy != null, policyValue,
                numbering != null, numberingValue, gradeTerms, cap != null, capValue));
    }

    /** Adds a grade's terms when the form sets them: blank is none (the sheet's terms). */
    private static void gradeTerms(Map<String, Integer> gradeTerms, String grade, String terms) throws InvalidSettingsException {
        if (terms == null) {
            return;
        }
        Integer value = null;
        if (!terms.trim().isEmpty()) {
            if (!DAYS.matcher(terms.trim()).matches()) {
                throw new InvalidSettingsException("The terms of grade " + grade + " must be a whole number of days, 0 or more, or blank.");
            }
            value = Integer.parseInt(terms.trim());
        }
        gradeTerms.put(grade, value);
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A sheet, chosen by its id; everything else in the app is kept per sheet. */
@Entity
@Table(name = "sheet")
public class Sheet {

    @Id
    private String id;

    /** The sheet's today: every date decision and default date uses it, never the real clock. */
    @Column(nullable = false)
    private LocalDate today;

    /** The clerk limit: a clerk settles a claim only when its due is at or below it; null when there is none. */
    @Column(name = "clerk_limit", precision = 19, scale = 2)
    private BigDecimal clerkLimit;

    /** The floor: a claim's live due is at least it; a sheet starts at 1.00. */
    @Column(nullable = false, precision = 19, scale = 2)
    private BigDecimal floor = Sheet.DEFAULT_FLOOR;

    /** The terms: a claim is due by its date plus this many days; a sheet starts at 14. */
    @Column(nullable = false)
    private int terms = Sheet.DEFAULT_TERMS;

    /** Grade A's own terms in days; null (blank) when it uses the sheet's terms. */
    @Column(name = "terms_a")
    private Integer termsA;

    /** Grade B's own terms in days; null (blank) when it uses the sheet's terms. */
    @Column(name = "terms_b")
    private Integer termsB;

    /** Grade C's own terms in days; null (blank) when it uses the sheet's terms. */
    @Column(name = "terms_c")
    private Integer termsC;

    /** The late percent: an overdue claim's due gains it of its figure for every full 30 days overdue; a sheet starts at 0.00. */
    @Column(name = "late_pct", nullable = false, precision = 19, scale = 2)
    private BigDecimal latePct = Sheet.DEFAULT_LATE_PCT;

    /** The policy date: a claim dated before it rounds half up, one on or after it half to even; null (blank) for
     *  the sheet's today. */
    @Column(name = "policy_date")
    private LocalDate policyDate;

    /** The period numbering from: while the sheet's today is on or after it, a claim opened is numbered within its
     *  period; null (blank) for off. */
    @Column(name = "period_numbering_from")
    private LocalDate periodNumberingFrom;

    /** The cap: a person's due-total is at most it; null (blank) when there is none. */
    @Column(precision = 19, scale = 2)
    private BigDecimal cap;

    /** The late percent a sheet starts at. */
    public static final BigDecimal DEFAULT_LATE_PCT = new BigDecimal("0.00");

    /** The terms a sheet starts at. */
    public static final int DEFAULT_TERMS = 14;

    /** The floor a sheet starts at. */
    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");

    protected Sheet() {
    }

    public Sheet(String id) {
        this.id = id;
        this.today = LocalDate.now(); // a new sheet starts on the real date
    }

    public String getId() {
        return id;
    }

    public LocalDate getToday() {
        return today;
    }

    public void setToday(LocalDate today) {
        this.today = today;
    }

    public BigDecimal getClerkLimit() {
        return clerkLimit;
    }

    public void setClerkLimit(BigDecimal clerkLimit) {
        this.clerkLimit = clerkLimit;
    }

    public BigDecimal getFloor() {
        return floor;
    }

    public void setFloor(BigDecimal floor) {
        this.floor = floor;
    }

    public int getTerms() {
        return terms;
    }

    public void setTerms(int terms) {
        this.terms = terms;
    }

    public BigDecimal getLatePct() {
        return latePct;
    }

    public void setLatePct(BigDecimal latePct) {
        this.latePct = latePct;
    }

    /** The grade's own terms in days (grades A, B and C); null when it has none and uses the sheet's terms. */
    public Integer getGradeTerms(String grade) {
        return switch (grade) {
            case "A" -> termsA;
            case "B" -> termsB;
            case "C" -> termsC;
            default -> null;
        };
    }

    public void setGradeTerms(String grade, Integer terms) {
        switch (grade) {
            case "A" -> termsA = terms;
            case "B" -> termsB = terms;
            case "C" -> termsC = terms;
            default -> throw new IllegalArgumentException("No such grade: " + grade);
        }
    }

    /** The terms in force for a grade: its own, else the sheet's. */
    public int termsFor(String grade) {
        Integer own = grade == null ? null : getGradeTerms(grade);
        return own != null ? own : terms;
    }

    public BigDecimal getCap() {
        return cap;
    }

    public void setCap(BigDecimal cap) {
        this.cap = cap;
    }

    public LocalDate getPolicyDate() {
        return policyDate;
    }

    public void setPolicyDate(LocalDate policyDate) {
        this.policyDate = policyDate;
    }

    /** The policy date in force: the one set, else the sheet's today. */
    public LocalDate policyDateInForce() {
        return policyDate != null ? policyDate : today;
    }

    public LocalDate getPeriodNumberingFrom() {
        return periodNumberingFrom;
    }

    public void setPeriodNumberingFrom(LocalDate periodNumberingFrom) {
        this.periodNumberingFrom = periodNumberingFrom;
    }

    /** Whether a claim opened now is numbered within its period: the period numbering is set and today is on or after it. */
    public boolean periodNumberingOn() {
        return periodNumberingFrom != null && !today.isBefore(periodNumberingFrom);
    }
}
